// Deterministic results. gen-reference.mjs runs this same function under
// Node and stores its answers in REFERENCE; the fixture runs it here and
// compares, so every expected value comes from Node's implementation.
export function compute(keys) {
  const out = {};
  for (const algorithm of ["md5", "sha1", "sha256", "sha384", "sha512"]) {
    out[`createHash ${algorithm}`] = crypto.createHash(algorithm).update("ab").update("c").digest("hex");
    out[`createHmac ${algorithm}`] = crypto.createHmac(algorithm, "key").update(message).digest("base64");
  }
  out["hash sha256"] = crypto.hash("sha256", message);
  out["pbkdf2Sync sha256"] = crypto.pbkdf2Sync("passwd", "salt", 1000, 64, "sha256").toString("hex");
  out["pbkdf2Sync sha512"] = crypto.pbkdf2Sync("passwd", "salt", 1000, 64, "sha512").toString("hex");
  out["hkdfSync sha256"] = Buffer.from(crypto.hkdfSync("sha256", "ikm", "salt", "info", 42)).toString("hex");
  // PKCS#1 v1.5 and Ed25519 signatures are deterministic.
  out["sign RSA-SHA256"] = crypto.sign("sha256", message, keys.rsa.private).toString("base64");
  out["sign RSA-SHA512"] = crypto.sign("sha512", message, keys.rsa.private).toString("base64");
  out["sign Ed25519"] = crypto.sign(null, message, keys.ed25519.private).toString("base64");
  for (const [name, pair] of Object.entries(keys)) {
    const priv = crypto.createPrivateKey(pair.private);
    const pub = crypto.createPublicKey(pair.private);
    out[`createPublicKey ${name}`] = pub.export({ type: "spki", format: "pem" });
    // Member order carries no meaning in a JWK, so it is compared sorted.
    const jwk = pub.export({ format: "jwk" });
    out[`export jwk ${name}`] = JSON.stringify(jwk, Object.keys(jwk).sort());
    out[`asymmetricKeyType ${name}`] = `${priv.asymmetricKeyType}/${pub.asymmetricKeyType}`;
  }
  // Every EC key exports as SEC1 and comes back from it, and a typed private
  // PEM yields its public half.
  for (const curve of ["p256", "p384", "p521"]) {
    const priv = crypto.createPrivateKey(keys[curve].private);
    const sec1 = priv.export({ type: "sec1", format: "der" });
    out[`export sec1 ${curve}`] = sec1.toString("base64");
    out[`import sec1 ${curve}`] = crypto
      .createPrivateKey({ key: sec1, format: "der", type: "sec1" })
      .export({ type: "pkcs8", format: "pem" });
    for (const type of ["pkcs8", "sec1"]) {
      const pem = priv.export({ type, format: "pem" });
      out[`createPublicKey ${curve} from ${type}`] = crypto
        .createPublicKey({ key: pem, format: "pem", type })
        .export({ type: "spki", format: "pem" });
    }
  }
  out["createSecretKey"] = crypto.createSecretKey(Buffer.from("0123456789abcdef")).export().toString("hex");
  return out;
}

function equal(actual, expected, what) {
  if (actual !== expected) throw new Error(`${what}: got ${actual}, want ${expected}`);
}

// Signature round trips for every key type, including randomized ECDSA:
// the reference signature verifies, a tampered message does not, and a
// signature made here verifies.
function roundTrip(name, hash, pair, reference) {
  const pub = crypto.createPublicKey(pair.private);
  if (reference) {
    equal(crypto.verify(hash, message, pub, Buffer.from(reference, "base64")), true, `${name}: reference verifies`);
  }
  const own = crypto.sign(hash, message, pair.private);
  equal(crypto.verify(hash, message, pub, own), true, `${name}: own signature verifies`);
  equal(crypto.verify(hash, tampered, pub, own), false, `${name}: tampered verifies`);
}

const checks = {
  reference() {
    const actual = compute(KEYS);
    const failed = Object.keys(REFERENCE).filter((key) => actual[key] !== REFERENCE[key]);
    if (failed.length) throw new Error(`differs from Node: ${failed.join(", ")}`);
    equal(Object.keys(actual).length, Object.keys(REFERENCE).length, "result count");
  },
  "sign and verify"() {
    roundTrip("RSA", "sha256", KEYS.rsa, REFERENCE["sign RSA-SHA256"]);
    roundTrip("Ed25519", null, KEYS.ed25519, REFERENCE["sign Ed25519"]);
    for (const curve of ["p256", "p384", "p521"]) {
      for (const hash of ["sha256", "sha384", "sha512"]) {
        roundTrip(`ECDSA ${curve} ${hash}`, hash, KEYS[curve], ECDSA[`${curve} ${hash}`]);
      }
    }
  },
  generateKeyPairSync() {
    // Each case names the key details Node reports for what was asked for,
    // so a generator that ignores the curve or the length fails here.
    const cases = [
      ["rsa", { modulusLength: 1024 }, "sha256", { modulusLength: 1024, publicExponent: 65537n }],
      ["ec", { namedCurve: "P-256" }, "sha256", { namedCurve: "prime256v1" }],
      ["ec", { namedCurve: "secp384r1" }, "sha384", { namedCurve: "secp384r1" }],
      ["ec", { namedCurve: "P-521" }, "sha512", { namedCurve: "secp521r1" }],
      ["ed25519", {}, null, {}],
    ];
    for (const [type, options, hash, details] of cases) {
      const a = crypto.generateKeyPairSync(type, options);
      equal(a.publicKey.asymmetricKeyType, type, `${type}: key type`);
      for (const [field, value] of Object.entries(details)) {
        equal(a.publicKey.asymmetricKeyDetails[field], value, `${type} ${JSON.stringify(options)}: ${field}`);
      }
      const b = crypto.generateKeyPairSync(type, options);
      const spki = (pair) => pair.publicKey.export({ type: "spki", format: "der" }).toString("hex");
      equal(spki(a) === spki(b), false, `${type}: two generated pairs are equal`);
      const sig = crypto.sign(hash, message, a.privateKey);
      equal(crypto.verify(hash, message, a.publicKey, sig), true, `${type}: verifies`);
      if (type === "ec") {
        const sec1 = a.privateKey.export({ type: "sec1", format: "pem" });
        const back = crypto.createPrivateKey(sec1);
        equal(back.asymmetricKeyDetails.namedCurve, details.namedCurve, `${options.namedCurve}: curve after a SEC1 round trip`);
      }
      const pem = a.privateKey.export({ type: "pkcs8", format: "pem" });
      const again = crypto.sign(hash, message, crypto.createPrivateKey(pem));
      equal(crypto.verify(hash, message, a.publicKey, again), true, `${type}: verifies after a PEM round trip`);
    }
  },
  "private key round trips"() {
    const pem = KEYS.rsa.private;
    const rsa = crypto.createPrivateKey(pem);
    const jwk = rsa.export({ format: "jwk" });
    equal(crypto.createPrivateKey({ key: jwk, format: "jwk" }).export({ type: "pkcs8", format: "pem" }), pem, "RSA private JWK");
    for (const cipher of ["aes-128-cbc", "aes-256-cbc"]) {
      const sealed = rsa.export({ type: "pkcs8", format: "pem", cipher, passphrase: "secret" });
      equal(crypto.createPrivateKey({ key: sealed, passphrase: "secret" }).export({ type: "pkcs8", format: "pem" }), pem, `encrypted PKCS#8 ${cipher}`);
    }
    const dsa = crypto.createPrivateKey(DSA_TRADITIONAL);
    equal(dsa.export({ type: "pkcs8", format: "pem" }), DSA_PKCS8, "traditional DSA as PKCS#8");
    equal(`${dsa.asymmetricKeyDetails.modulusLength}/${dsa.asymmetricKeyDetails.divisorLength}`, "2048/224", "traditional DSA sizes");
  },
  "random and comparison"() {
    equal(crypto.randomBytes(32).length, 32, "randomBytes length");
    equal(crypto.randomBytes(16).equals(crypto.randomBytes(16)), false, "two random draws are equal");
    equal(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(crypto.randomUUID()), true, "randomUUID format");
    equal(crypto.timingSafeEqual(Buffer.from("same"), Buffer.from("same")), true, "equal buffers");
    equal(crypto.timingSafeEqual(Buffer.from("same"), Buffer.from("diff")), false, "different buffers");
  },
  async callbacks() {
    const derived = await new Promise((resolve, reject) =>
      crypto.pbkdf2("passwd", "salt", 1000, 64, "sha256", (error, key) => (error ? reject(error) : resolve(key))),
    );
    equal(derived.toString("hex"), REFERENCE["pbkdf2Sync sha256"], "pbkdf2 callback");
  },
};

export default {
  async fetch(request) {
    if (new URL(request.url).pathname === "/__ready") return new Response("ready");
    const results = {};
    for (const [name, check] of Object.entries(checks)) {
      try {
        await check();
        results[name] = "ok";
      } catch (error) {
        results[name] = `fail: ${error?.message ?? error}`;
      }
    }
    return Response.json(results);
  },
};
